type NotifyManyParams struct {
	Reference string
	Targets   []string
}

type NotifyManyRow struct {
	ID        string
	AccountID string
}

func (q *Queries) NotifyMany(ctx context.Context, arg NotifyManyParams) ([]NotifyManyRow, error) {
	rows, err := q.db.Query(ctx, notifyMany, arg.Reference, arg.Targets)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []NotifyManyRow{}
	for rows.Next() {
		var i NotifyManyRow
		if err := rows.Scan(&i.ID, &i.AccountID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

